export function complex(v: number): number {
  let total = 0
  if (v > 1) total += 1
  if (v > 2) total += 1
  if (v > 3) total += 1
  if (v > 4) total += 1
  if (v > 5) total += 1
  if (v > 6) total += 1
  if (v > 7) total += 1
  if (v > 8) total += 1
  if (v > 9) total += 1
  if (v > 10) total += 1
  if (v > 11) total += 1
  if (v > 12) total += 1
  if (v > 13) total += 1
  if (v > 14) total += 1
  if (v > 15) total += 1
  if (v > 16) total += 1
  return total
}
